contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We choose inputs: account address to act for and an amount to open as maker or taker,
    // and a boolean chooseMaker to pick openMakeFor (true) or openTakeFor (false).
    // We will (1) record latestVersion before, (2) try to call the chosen open function
    // as this contract (which is allowed since onlyAccountOrMultiInvoker allows msg.sender==account),
    // capturing whether it reverted, then (3) read latestVersion after and check the rule:
    // - If call did not revert, the position fee charged (if any) observed via collateral settlement can't be read directly,
    //   but we can observe that latestVersion did not increase as a result of openMakeFor/openTakeFor (these only write pre positions)
    // - Also, the function may emit PositionFeeCharged, but we can't read events here. We instead assert that latestVersion() after equals before when call succeeds.
    // We also assert that if the call succeeded then it did not revert (trivial) and that the function did not increase latestVersion.

    function run(address account, uint256 amount, bool chooseMaker) public payable {
        require(account != address(0));
        // record before-version
        uint256 before = c.latestVersion();

        bool reverted;
        // call chosen open, catch revert
        if (chooseMaker) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 after = c.latestVersion();

        // General rule asserted: if the open call succeeded, latestVersion() must be unchanged (open creates pre-positions not new oracle versions).
        // Also ensure when succeeded, it truly did not revert (reverted==false). This is a conjunct that relates inputs, call result, and observable state.
        assert((reverted == false) ? after == before : true);
    }

    // accept Ether if needed by collateral interactions
    receive() external payable {}
}

