    // single public entrypoint for property-based testing
    function run(address account, uint256 amountRaw, bool isMake, address operator) public payable {
        // normalize amount into a UFixed18-like packed uint by treating amountRaw as whole units
        // no precondition on c state
        require(amountRaw <= type(uint128).max);

        // read product latestVersion before calls
        uint256 beforeLatest = c.latestVersion();
        uint256 beforeAccountLatest = c.latestVersion(account);

        // decide which action to attempt; we call via the public functions
        bool reverted;
        // Prepare a UFixed18 value via the public factory: UFixed18Lib.from(uint256) is internal, so pass encoded as uint
        // The contract expects UFixed18 type in params; solidity will accept uint256 and convert implicitly when calling
        uint256 amount = amountRaw;

        // Ensure msg.sender for c calls is this contract; that's true. Some functions require notPaused/other modifiers,
        // but we cannot set controller etc. We'll try both openMakeFor and openTakeFor which may revert.
        if (isMake) {
            // try openMakeFor(account, UFixed18(amount))
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read latestVersion after call
        uint256 afterLatest = c.latestVersion();
        uint256 afterAccountLatest = c.latestVersion(account);

        // The intended general rule:
        // If the call did not revert then the account's latestVersion must advance to equal the product latestVersion (i.e., account is settled up-to-date).
        // If it reverted then the account latestVersion must be unchanged.
        assert(
            (!reverted && afterAccountLatest == afterLatest) ||
            (reverted && afterAccountLatest == beforeAccountLatest)
        );
    }

    receive() external payable {}
}

