contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // amount is interpreted in raw uint256 units for UFixed18 (caller must fit packing)
    function run(address account, uint256 amount) public payable {
        require(account != address(0), "zero account");

        // Read pre-state via public getter pre(account) which returns (uint256, Position, Position)
        (uint256 vBefore, uint256 makerBefore_u, uint256 makerBefore_t) = _readPreOpenMaker(account);

        bool reverted;
        // perform the state-changing call at top-level; wrap amount into UFixed18 by calling UFixed18Lib.from is not available here,
        // but the contract C expects UFixed18 in its ABI (it's a uint256 typedef). We pass amount directly.
        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        (uint256 vAfter, uint256 makerAfter_u, uint256 makerAfter_t) = _readPreOpenMaker(account);

        // The rule: if the call did not revert, the observed openPosition.maker (makerAfter_u) must be >= makerBefore_u
        // When it reverts we make no claim. We use the public getter only.
        assert(reverted || makerAfter_u >= makerBefore_u);
    }

    // Helper to read the pre(account) return values and extract the openPosition.maker (as uint256)
    function _readPreOpenMaker(address account) private returns (uint256, uint256, uint256) {
        // The public getter pre(account) has the Solidity-generated signature that returns (uint256, (uint256,uint256), (uint256,uint256))
        // but ABI flattens nested tuples; call it and decode the obvious parts by calling the view function.
        // Since we are restricted to using only public interface of c, call the view function and capture its returns via a low-level staticcall.
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("pre(address)", account));
        require(ok, "pre view failed");
        // Decoding: (uint256 oracleVersion, (uint256 open_maker, uint256 open_taker), (uint256 close_maker, uint256 close_taker))
        (uint256 oracleVersion, uint256 openMaker, uint256 openTaker, uint256 closeMaker, uint256 closeTaker) = abi.decode(ret, (uint256, uint256, uint256, uint256, uint256));
        return (oracleVersion, openMaker, openTaker);
    }

    receive() external payable {}
}

