contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters: account to act for and an amount to open/close (UFixed18 as uint256 scaled by 1e18)
    // We use a uint256 amount which maps to UFixed18 via the public functions that accept UFixed18 (ABI-compatible)
    function run(address account, uint256 amount) public payable {
        require(account != address(0));
        // Ensure we can call functions that may charge position fees by having some ether is not required here
        // Record pre-state: whether account is liquidating initially (should be false on fresh product but we observe)
        bool beforeLiquidating = c.isLiquidating(account);

        // Attempt openMakeFor and capture revert status
        bool openReverted;
        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        // Attempt closeMakeFor and capture revert status
        bool closeReverted;
        try c.closeMakeFor(account, UFixed18.wrap(amount)) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        // Observe final liquidation flag
        bool afterLiquidating = c.isLiquidating(account);

        // General rule: if both operations succeeded (did not revert), then account must not be marked liquidating afterwards.
        // Also allow that if it was liquidating before, it may remain so; so we only assert when beforeLiquidating was false.
        assert(!( !openReverted && !closeReverted && !beforeLiquidating) || (afterLiquidating == false));
    }

    // Minimal receive to accept ETH if needed by future interactions
    receive() external payable {}
}

