        // get account pre position before
        (uint256 preOracleBefore, , ) = c.pre(account);
        // call openMakeFor and detect revert
        bool reverted;
        // construct UFixed18 via UFixed18Lib.from(uint256) is not visible here; we must pass a raw uint256
        // The external API expects UFixed18 type; solidity will accept uint256 for that typedef
        try c.openMakeFor(account, UFixed18.wrap(amountRaw)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterLatest = c.latestVersion();
        (uint256 preOracleAfter, , ) = c.pre(account);

        // If the call did not revert, then the account's pre().oracleVersion should either be updated to latestVersion()
        // or the product might be closed (so no change enforced), or latestVersion may have been unchanged.
        // This encodes that a successful openMakeFor results in a deterministic pre-state tied to the product's version.
        assert(
            reverted || closedOrSameOrPreMatches(beforeLatest, afterLatest, preOracleAfter)
        );
    }

    // helper view used only in assert; allowed to call c.view functions
    function closedOrSameOrPreMatches(uint256 beforeLatest, uint256 afterLatest, uint256 preOracleAfter) internal view returns (bool) {
        bool isClosed = c.closed();
        if (isClosed) return true;
        if (beforeLatest == afterLatest) return true;
        // otherwise require that the account's pre oracle version equals the latestVersion()
        return preOracleAfter == afterLatest;
    }

    receive() external payable {}
}
